{
  "roadmap": {
    "project_id": "regorus-policy-eval",
    "created_at": "2026-04-07T16:57:38Z",
    "total_steps": 14,
    "phases": 3,
    "notes": "UI steps (Phase 2, 03-03) have no test_file references — UI acceptance is manual browser testing. Backend API they consume is tested via acceptance tests."
  },
  "phases": [
    {
      "id": "01",
      "name": "Backend Engine + Schema",
      "steps": [
        {
          "id": "01-01",
          "name": "Vendor Regorus WASM and load in Bun",
          "criteria": "Regorus WASM loads successfully and remains cached. Unit test compiles a hardcoded Rego string and queries allow/deny. vendor/regorus-src/ submodule and vendor/regorus-wasm/ build output committed.",
          "test_file": "tests/unit/rego-evaluator.test.ts",
          "scenario_name": "compiles and evaluates hardcoded Rego policy"
        },
        {
          "id": "01-02",
          "name": "Schema migration: replace condition with rego_source",
          "criteria": "schema/migrations/0088_replace_condition_with_rego_source.surql created. Removes rules fields, adds rego_source string. bun migrate applies cleanly. INFO FOR TABLE policy shows rego_source field.",
          "test_file": "",
          "scenario_name": ""
        },
        {
          "id": "01-03",
          "name": "RegoEvaluator: compile, evaluate, map result",
          "criteria": "compileRego() returns success or errors with line/column. Policy evaluation returns decision (allow/deny with messages) and optional evidence requirement. Package validation rejects non-osabio.policy packages. Fail-closed on no match. Engine cache by policyId:version.",
          "test_file": "tests/unit/rego-evaluator.test.ts",
          "scenario_name": "evaluateRegoPolicy returns allow, deny with messages, evidence requirement, and fail-closed on no match"
        },
        {
          "id": "01-04",
          "name": "Wire RegoEvaluator into policy gate, remove predicate evaluator",
          "criteria": "evaluatePolicyGate() uses Rego evaluator for each policy. predicate-evaluator.ts deleted. PolicyRecord uses rego_source. Signature unchanged. Walking skeleton passes: create Rego policy, activate, evaluate intent, verify deny/allow and trace. WASM failure returns deny with error reason.",
          "test_file": "tests/acceptance/policy-node/walking-skeleton.test.ts",
          "scenario_name": "active deny policy blocks a deploy intent and records policy trace"
        },
        {
          "id": "01-05",
          "name": "Rego compilation validation on policy create/update",
          "criteria": "Invalid Rego rejected with {line, column, message}. Wrong package rejected. Valid Rego accepted. Legacy rules field rejected. policy-validation.ts rewritten for Rego compilation. Unit and route-level validation tested.",
          "test_file": "tests/unit/policy-validation.test.ts",
          "scenario_name": "rejects invalid Rego syntax with line/column errors"
        },
        {
          "id": "01-06",
          "name": "Update acceptance tests for Rego policy lifecycle",
          "criteria": "All tests in policy-node/ pass with rego_source payloads. policy-test-kit.ts types updated. Milestone-1 and milestone-2 tests cover create, activate, deprecate, version, deny short-circuit, allow, fail-closed, evidence requirement, human veto.",
          "test_file": "tests/acceptance/policy-node/milestone-2-policy-gate-evaluation.test.ts",
          "scenario_name": "deny rule at priority 100 blocks intent before lower-priority allow rule is evaluated"
        }
      ]
    },
    {
      "id": "02",
      "name": "UI — Rego Editor + Validation",
      "steps": [
        {
          "id": "02-01",
          "name": "Add CodeMirror 5 with codemirror-rego dependency",
          "criteria": "codemirror, codemirror-rego, and react-codemirror2 installed. A minimal RegoEditor component renders with Rego syntax highlighting, line numbers, and bracket matching.",
          "test_file": "",
          "scenario_name": ""
        },
        {
          "id": "02-02",
          "name": "Replace RuleBuilder with RegoEditor in CreatePolicyDialog",
          "criteria": "CreatePolicyDialog renders RegoEditor instead of RuleBuilder. Form submits rego_source to POST /policies. Field reference panel shows IntentEvaluationContext fields. RuleBuilder.tsx deleted.",
          "test_file": "",
          "scenario_name": ""
        },
        {
          "id": "02-03",
          "name": "Add Validate button with inline error display",
          "criteria": "Validate button calls POST /policies/validate. Success shows green checkmark. Failure shows errors with line numbers. CodeMirror gutter markers highlight error lines.",
          "test_file": "",
          "scenario_name": ""
        },
        {
          "id": "02-04",
          "name": "Display rego_source on policy detail page",
          "criteria": "PolicyDetailPage renders rego_source in read-only CodeMirror with Rego syntax highlighting. No edit capability in detail view.",
          "test_file": "",
          "scenario_name": ""
        },
        {
          "id": "02-05",
          "name": "Version diff view for Rego source",
          "criteria": "VersionDiffView shows diff of rego_source between two policy versions. Uses CodeMirror merge addon or text diff component.",
          "test_file": "",
          "scenario_name": ""
        }
      ]
    },
    {
      "id": "03",
      "name": "Policy Test Endpoint + Panel",
      "steps": [
        {
          "id": "03-01",
          "name": "Backend: POST /policies/:id/test endpoint",
          "criteria": "Accepts mock IntentEvaluationContext JSON, evaluates rego_source, returns { decision, messages, evidence_requirement?: { min_count, required_types? } }. 404 for missing policy. 400 for invalid input. Requires workspace authentication.",
          "test_file": "tests/acceptance/policy-node/milestone-3-rego-test-endpoint.test.ts",
          "scenario_name": "test policy with mock input that triggers deny"
        },
        {
          "id": "03-02",
          "name": "Backend: POST /policies/validate endpoint",
          "criteria": "Accepts { rego_source }, compiles via Regorus, returns { success } or { success: false, errors: [{ line, column, message }] }. No policy record created. Requires workspace authentication.",
          "test_file": "tests/acceptance/policy-node/milestone-3-rego-test-endpoint.test.ts",
          "scenario_name": "validate endpoint returns compilation errors for invalid Rego"
        },
        {
          "id": "03-03",
          "name": "UI: PolicyTestPanel component",
          "criteria": "PolicyTestPanel on policy detail page. JSON editor for mock input. Test button calls POST /policies/:id/test. Displays decision with messages. Handles error states (400, 404, network).",
          "test_file": "",
          "scenario_name": ""
        }
      ]
    }
  ],
  "implementation_scope": {
    "source_directories": [
      "app/src/server/policy/",
      "app/src/client/components/policy/",
      "vendor/regorus-wasm/",
      "schema/migrations/"
    ],
    "test_directories": [
      "tests/unit/",
      "tests/acceptance/policy-node/"
    ],
    "excluded_patterns": [
      "node_modules/**",
      "vendor/regorus-src/**"
    ]
  },
  "validation": {
    "status": "approved",
    "reviewer": "nw-solution-architect-reviewer",
    "approved_at": "2026-04-08"
  }
}
